package app.officinalibri;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.*;import android.webkit.*;import android.view.*;import androidx.webkit.WebViewAssetLoader;import org.json.*;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private static final String ORIGIN="https://appassets.androidplatform.net";
    private DriveConnection drive;private WebView web;private android.widget.FrameLayout frame;private MobileStore store;private final ExecutorService io=Executors.newSingleThreadExecutor();
    private String pickerId,pickerMethod,imageBook;private File pendingExport;
    @Override public void onCreate(Bundle state){super.onCreate(state);try{
        store=new MobileStore(getFilesDir());drive=new DriveConnection(this,store,io,this::reply);frame=new android.widget.FrameLayout(this);frame.setBackgroundColor(Color.parseColor("#f8f6fb"));web=new WebView(this);frame.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));setContentView(frame);
        if(Build.VERSION.SDK_INT>=30){frame.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets edges=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());view.setPadding(edges.left,edges.top,edges.right,edges.bottom);return insets;});frame.requestApplyInsets();}else frame.setFitsSystemWindows(true);
        WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);
        WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).addPathHandler("/books/",this::resource).addPathHandler("/thumbs/",this::thumbnail).build();
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){Uri u=request.getUrl();return !("https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost())&&"/assets/index.html".equals(u.getPath()));}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!"https".equals(u.getScheme())||!"appassets.androidplatform.net".equals(u.getHost()))return empty();WebResourceResponse response=loader.shouldInterceptRequest(u);return response==null?empty():response;}});
        web.addJavascriptInterface(new Bridge(),"OfficinaNative");web.loadUrl(ORIGIN+"/assets/index.html");
    }catch(Exception e){new AlertDialog.Builder(this).setTitle("Avvio non riuscito").setMessage(e.getMessage()).setPositiveButton("Chiudi",(d,w)->finish()).show();}}
    private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",404,"Not found",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
    private WebResourceResponse resource(String path){try{String[] parts=path.split("/",3);if(parts.length!=3||!parts[0].matches("[a-f0-9-]{36}")||!MobileStore.allowed(parts[1]+"/"+parts[2])||!Arrays.asList("assets","novel-fonts").contains(parts[1]))return empty();File file=new File(store.folder(parts[0]),parts[1]+"/"+parts[2]);String mime=parts[2].endsWith(".png")?"image/png":parts[2].endsWith(".jpg")?"image/jpeg":parts[2].endsWith(".otf")?"font/otf":"font/ttf";return new WebResourceResponse(mime,null,new FileInputStream(file));}catch(Exception e){return empty();}}
    private WebResourceResponse thumbnail(String path){try{String[] parts=path.split("/",2);if(parts.length!=2||!parts[1].matches("[a-f0-9]{64}\\.(png|jpg)"))return empty();File file=new File(store.folder(parts[0]),"assets/"+parts[1]);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),options);int scale=1;while(Math.max(options.outWidth,options.outHeight)/scale>1024)scale*=2;options.inJustDecodeBounds=false;options.inSampleSize=scale;Bitmap image=BitmapFactory.decodeFile(file.getPath(),options);if(image==null)return empty();ByteArrayOutputStream bytes=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,bytes);image.recycle();return new WebResourceResponse("image/png",null,new ByteArrayInputStream(bytes.toByteArray()));}catch(Exception e){return empty();}}
    private void reply(String id,Object value,Exception error){runOnUiThread(()->{try{JSONObject response=new JSONObject().put("id",id).put("ok",error==null);if(error==null)response.put("value",value==null?JSONObject.NULL:value);else response.put("error",error.getMessage()==null?"Operazione non completata":error.getMessage());web.evaluateJavascript("window.__officinaReply("+response+")",null);}catch(Exception ignored){}});}
    public final class Bridge {
        @JavascriptInterface public void request(String payload){io.execute(()->{String id="";try{JSONObject request=new JSONObject(payload);id=request.getString("id");String method=request.getString("method");JSONObject a=request.optJSONObject("args");if(a==null)a=new JSONObject();Object value=null;if(method.startsWith("drive")){drive.request(id,method,a);return;}
            switch(method){
                case "journeyLoad":value=new JourneyStore(store).load(a.getString("id"));break;
                case "journeySave":value=new JourneyStore(store).save(a.getString("id"),a.getJSONObject("journey"));break;
                case "journeyApprove":value=new JourneyStore(store).approve(a.getString("id"),a);break;
                case "journeyReview":value=new JourneyStore(store).review(a.getString("id"),a);break;
                case "journeyHistory":value=new JourneyStore(store).history(a.getString("id"));break;
                case "journeyRestore":value=new JourneyStore(store).restore(a.getString("id"),a.getString("name"),a.getInt("revision"));break;
                case "list":value=store.list();break;
                case "notices":{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=getAssets().open("THIRD_PARTY_NOTICES.txt")){byte[] buf=new byte[4096];for(int n;(n=in.read(buf))!=-1;)bytes.write(buf,0,n);}value=new String(bytes.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);break;}
                case "read":value=store.read(a.getString("id"));break;
                case "create":value=store.create(a);break;
                case "save":value=store.save(a.getString("id"),a.getJSONObject("novel"),a.optBoolean("checkpoint",false));break;
                case "discard":store.discard(a.getString("id"));break;
                case "accept":value=store.accept(a.getString("id"));break;
                case "history":value=store.history(a.getString("id"));break;
                case "restore":value=store.restore(a.getString("id"),a.getString("name"),a.getInt("revision"));break;
                case "import":case "image":case "export":{String callId=id,callMethod=method;JSONObject args=a;runOnUiThread(()->pick(callId,callMethod,args));return;}
                case "theme":{boolean dark=a.optBoolean("dark");runOnUiThread(()->{int color=Color.parseColor(dark?"#1c202c":"#f8f6fb");frame.setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);int flags=dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;getWindow().getDecorView().setSystemUiVisibility(flags);});break;}
                case "exit":runOnUiThread(()->finish());break;
                default:throw new IOException("Comando Android non riconosciuto");
            }reply(id,value,null);
        }catch(Exception e){reply(id,null,e);}});}
    }
    private void pick(String id,String method,JSONObject args){if(pickerId!=null){reply(id,null,new IOException("Completa prima la selezione aperta"));return;}pickerId=id;pickerMethod=method;try{
        if(method.equals("export")){String bookId=args.getString("id");io.execute(()->{try{pendingExport=File.createTempFile("officina-",".officinazip",getCacheDir());store.exportArchive(bookId,new FileOutputStream(pendingExport));runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"Officina-Libri-copia.officinazip");startActivityForResult(intent,40);});}catch(Exception e){reply(pickerId,null,e);pickerId=null;}});return;}
        Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(method.equals("image")?"image/*":"*/*");if(method.equals("image"))imageBook=args.getString("id");startActivityForResult(intent,40);
    }catch(Exception e){pickerId=null;reply(id,null,e);}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(drive!=null&&drive.activityResult(request,result,data))return;if(request!=40||pickerId==null)return;String id=pickerId,method=pickerMethod,bookId=imageBook;File output=pendingExport;pickerId=null;pendingExport=null;if(result!=RESULT_OK||data==null||data.getData()==null){if(output!=null)output.delete();reply(id,null,null);return;}Uri uri=data.getData();io.execute(()->{try{Object value;if(method.equals("export")){try(InputStream in=new FileInputStream(output);OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("Destinazione non disponibile");byte[] buf=new byte[65536];for(int n;(n=in.read(buf))!=-1;)out.write(buf,0,n);}output.delete();value=new JSONObject().put("exported",true);}else if(method.equals("import")){InputStream in=getContentResolver().openInputStream(uri);if(in==null)throw new IOException("File non disponibile");value=store.importArchive(in);}else value=addImage(bookId,uri);reply(id,value,null);}catch(Exception e){if(output!=null)output.delete();reply(id,null,e);}});}
    private JSONObject addImage(String id,Uri uri)throws Exception {File temp=File.createTempFile("image-",".tmp",getCacheDir());try{long bytes=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("Immagine non disponibile");byte[] buf=new byte[65536];for(int n;(n=in.read(buf))!=-1;){bytes+=n;if(bytes>40L*1024*1024)throw new IOException("Immagine oltre 40 MiB");out.write(buf,0,n);}}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),options);String ext="image/png".equals(options.outMimeType)?"png":"image/jpeg".equals(options.outMimeType)?"jpg":null;if(ext==null||options.outWidth<1||(long)options.outWidth*options.outHeight>60000000)throw new IOException("Scegli un PNG/JPEG entro 60 milioni di pixel");String hash=MobileStore.hash(temp),name=hash+"."+ext;File target=new File(store.folder(id),"assets/"+name);Files.createDirectories(target.getParentFile().toPath());if(!target.exists())Files.copy(temp.toPath(),target.toPath());if(!MobileStore.hash(target).equals(hash))throw new IOException("Immagine non integra");return new JSONObject().put("name",name).put("metadata",new JSONObject().put("sha256",hash).put("mime",options.outMimeType).put("width",options.outWidth).put("height",options.outHeight).put("bytes",bytes));}finally{temp.delete();}}
    @Override public void onBackPressed(){if(web!=null)web.evaluateJavascript("window.__officinaBack && window.__officinaBack()",null);else super.onBackPressed();}
    @Override protected void onPause(){if(web!=null)web.evaluateJavascript("window.__officinaFlush && window.__officinaFlush()",null);super.onPause();}
    @Override protected void onDestroy(){if(drive!=null)drive.close();io.shutdown();if(web!=null){web.removeJavascriptInterface("OfficinaNative");web.destroy();}super.onDestroy();}
}
